-- 참고:
--   정본 = 롯데백화점 공식 채용 페이지 복지와 혜택(그리팅 · 꼬리말 롯데쇼핑 주식회사 · SSR 원본 HTML) — 롯데쇼핑 백화점사업부 페이지.
--   보조 = 롯데쇼핑 2025 지속가능경영보고서(minfo.lotteshopping.com · 2026-08 발행 · 보고 기간 2025-01~12 · 보고 범위 롯데쇼핑 및 각 사업부 국내 전 사업장)
--          39 · 41 · 43 · 44 · 45 · 46 · 49쪽 · 롯데마트 공식 채용 페이지(recruit.lottemart.com · 인증서 주체 롯데쇼핑 롯데마트사업본부) 복리후생 · 교육제도 · 급여체계 ·
--          롯데백화점 채용 페이지 성장하는 문화 · 2026 반기보고서(접수 20260814003975) 유연근무제도 사용 현황.
--   귀속: 모두 롯데쇼핑 한 법인의 사업부(백화점 · 마트 · 슈퍼 · e커머스) 자료 — 그룹 각주 없음. 사업부 한정 문장은 이름 끝 「(○○부문)」 + 서술 출처에 사업부.
--         네 사업부에 다 걸친 포상 · 공시 표의 유연근무 두 행만 한정 없음.
--   금액: 금액 행 0 — 최대 · 한도 · 분기 · 반기 · 비율 · 1회성 숫자뿐이라 전부 정성.
--   제외: 법정(육아휴직 1년 · 육아기 근로시간 단축 · 태아검진 휴가 · 4대 보험 · 재취업 교육 · 유소견자 사후관리) · 업무 교육(온보딩 · 리더십 · 직무 교육) · 업무대행 수당 · 칭찬 제도.
--   공고 근거 0행 / 전체 36행 · SORT 섹션 = perks 10~20(11행) · family 30 · time_off 40 · leisure 50 · growth 60 · health 70 · flexibility 80 · compensation 90 · work_env 100.
-- 검증 · 감사 판정 반영(2026-10-15): 롯데마트 교육제도 페이지(2022 이전 판)에만 기댄 사외 MBA 행 삭제 · 어학 · 교육 행에서 그 페이지 구절 걷기 · 단체보험 행에서 4대 보험 칸 구절 걷기 · 임신 출산 육아 행 문안 교체와 16쪽 일맘 CLUB 워크숍 병합 · 두 사업부 이상 같은 제도 12행 이름에서 부문 떼기(참고 블록 보조 줄의 롯데마트 교육제도는 이 판정으로 뒤집힘) · 항목 페이지 예외 1(통합 밖 리드 집행) — 최종 35행
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

-- 1) 회사 등록 (신규 — 이 INSERT 가 실제 등록을 수행한다)
INSERT IGNORE INTO TCOMPANY (COMP_ENG_NM, COMP_NM, COMP_TP_ID, INDUSTRY_NM, LOGO_NM, CAREERS_BENEFIT_URL)
VALUES ('lotte_shopping', '롯데쇼핑',
        (SELECT COMP_TP_ID FROM TCOMPANY_TYPE WHERE COMP_TP_CD = 'large'),
        '유통', 'L', 'https://career.lotteshopping.com/ko/benefit');

-- 2) COMP_ID 조회
SET @comp_id = (SELECT COMP_ID FROM TCOMPANY WHERE COMP_ENG_NM = 'lotte_shopping');

-- 3) CAREERS_BENEFIT_URL 갱신 (이미 행이 있으면 INSERT IGNORE 로는 안 바뀐다)
UPDATE TCOMPANY SET CAREERS_BENEFIT_URL = 'https://career.lotteshopping.com/ko/benefit'
 WHERE COMP_ID = @comp_id;

-- 4) 기존 추정 데이터 삭제 (official 보존)
DELETE FROM TCOMPANY_BENEFIT WHERE COMP_ID = @comp_id AND BADGE_CD = 'est';

